-- ============================================================
-- Lab 22 -- The same pipeline as a dbt project on Snowflake
--
-- Creates COCO_WS_LAB22_DB_<you>.LAB with the SAME raw landing table
-- that Lab 21 builds, generated by the same arithmetic and the same
-- hash seeds. That is deliberate: the point of this lab is that the
-- models you get out of dbt should agree with the dynamic tables from
-- Lab 21 row for row. If they do not, one of them is wrong.
--
-- The trap this lab is built around:
--
--   An incremental model with a missing or wrong `unique_key` still
--   builds, still reports success, and quietly reintroduces the
--   duplicate events that Lab 21's QUALIFY ROW_NUMBER() removed.
--   dbt does not warn. The row count is simply wrong, and it is wrong
--   only after the SECOND run -- the first full build looks perfect.
--
-- So the raw data is messy in exactly the same ways as Lab 21:
--   - exact duplicate events (at-least-once delivery)
--   - two different timestamp encodings in the same column
--   - missing customer ids on some rows
--   - a nested line-item array that needs flattening
--
-- What this file does NOT create: the dbt project, the models, or the
-- dbt project object. You and CoCo build those during the lab. A
-- reference implementation is in queries/reference_project/ for the
-- presenter.
--
-- Re-runnable: per-lab objects use CREATE OR REPLACE.
-- Teardown: labs/22-build-a-pipeline-with-dbt/cleanup.sql
-- ============================================================

-- ------------------------------------------------------------
-- Per-user namespace
--
-- Every object this lab creates at ACCOUNT level -- the database and
-- the warehouse -- is suffixed with your user name, so a whole room
-- can run this lab in one Snowflake account without colliding.
-- Everything INSIDE the database (schema LAB, and every table and
-- view) keeps its usual name, so the SQL below reads identically for
-- everyone.
--
-- Two things worth knowing:
--   * Session variables live only for this session, so every file in
--     the workshop sets its own. Run the file top to bottom.
--   * CoCo runs its SQL in its own session, so it does NOT see these
--     variables. The last query in this file prints your real object
--     names -- paste those into a prompt rather than $LAB_DB.
-- ------------------------------------------------------------
SET NS            = (SELECT REGEXP_REPLACE(CURRENT_USER(), '[^A-Za-z0-9]', '_'));
SET WH            = 'COCO_WS_WH_' || $NS;
SET SHARED_DB     = 'COCO_WS_SHARED_DB_' || $NS;
SET SHARED_SCHEMA = $SHARED_DB || '.WORKSHOP';
SET RUN_LOG       = $SHARED_DB || '.WORKSHOP.LAB_RUN_LOG';
SET LAB_DB        = 'COCO_WS_LAB22_DB_' || $NS;

-- ------------------------------------------------------------
-- Shared bootstrap (safe to re-run, safe if another lab did it)
-- ------------------------------------------------------------
CREATE WAREHOUSE IF NOT EXISTS IDENTIFIER($WH)
  WAREHOUSE_SIZE = 'XSMALL' AUTO_SUSPEND = 60 AUTO_RESUME = TRUE
  INITIALLY_SUSPENDED = TRUE
  COMMENT = 'CoCo Interactive Workshop -- shared compute for all labs';
USE WAREHOUSE IDENTIFIER($WH);

CREATE DATABASE IF NOT EXISTS IDENTIFIER($SHARED_DB)
  COMMENT = 'CoCo Interactive Workshop -- shared workshop metadata';
CREATE SCHEMA IF NOT EXISTS IDENTIFIER($SHARED_SCHEMA);
CREATE TABLE IF NOT EXISTS IDENTIFIER($RUN_LOG) (
  LAB_ID VARCHAR(16), LAB_NAME VARCHAR(200), EVENT_TYPE VARCHAR(20),
  EVENT_TS TIMESTAMP_LTZ, USER_NAME VARCHAR(200), ROLE_NAME VARCHAR(200),
  WAREHOUSE_NAME VARCHAR(200), SESSION_ID VARCHAR(50), QUERY_TAG VARCHAR(200)
);

ALTER SESSION SET QUERY_TAG = 'COCO_WS_LAB22';

-- ------------------------------------------------------------
-- Lab database -- raw layer only
--
-- Two schemas, because a dbt project needs somewhere to write that is
-- not where it reads:
--   LAB      the raw source, and the schema the profile targets
--   LAB_DBT  where dbt puts its own models, so a failed run cannot
--            damage the source and you can drop it and start over
-- ------------------------------------------------------------
CREATE OR REPLACE DATABASE IDENTIFIER($LAB_DB)
  COMMENT = 'CoCo Workshop Lab 22 -- the Lab 21 pipeline as a dbt project';
USE DATABASE IDENTIFIER($LAB_DB);
CREATE OR REPLACE SCHEMA LAB;
CREATE OR REPLACE SCHEMA LAB_DBT
  COMMENT = 'Target schema for the dbt project. Safe to drop and rebuild.';
USE SCHEMA LAB;

CREATE OR REPLACE TABLE RAW_ORDER_EVENTS (
  RAW_ID       NUMBER(38,0),
  PAYLOAD      VARIANT,
  SOURCE_FILE  VARCHAR(200),
  INGESTED_AT  TIMESTAMP_LTZ
) COMMENT = 'Landing zone for order events from the storefront. At-least-once delivery, so duplicates are expected.';

-- ------------------------------------------------------------
-- Generate the raw events
--
-- Byte-for-byte the same generator as Lab 21, including every hash
-- seed. Do not "improve" it here: the moment the two diverge, the
-- comparison between the dbt models and the dynamic tables stops
-- meaning anything, and this lab's whole argument rests on it.
-- ------------------------------------------------------------
INSERT INTO RAW_ORDER_EVENTS (RAW_ID, PAYLOAD, SOURCE_FILE, INGESTED_AT)
WITH base AS (
  SELECT
    SEQ4() + 1                                  AS n,
    'EVT-' || LPAD(SEQ4() + 1, 8, '0')          AS event_id,
    DATEADD('second',
            MOD(ABS(HASH(SEQ4(), 7)), 86400 * 60) * -1,
            CURRENT_TIMESTAMP())                AS ts
  FROM TABLE(GENERATOR(ROWCOUNT => 40000))
)
SELECT
  b.n,
  OBJECT_CONSTRUCT_KEEP_NULL(
    'event_id',    b.event_id,
    'event_type',  DECODE(MOD(ABS(HASH(b.n, 13)), 10),
                          0, 'order_cancelled', 1, 'order_refunded', 'order_placed'),
    -- Two encodings in one field. Half the rows are epoch milliseconds
    -- as a number, half are ISO-8601 strings, because two services
    -- write to the same topic.
    'occurred_at', IFF(MOD(b.n, 2) = 0,
                       TO_VARCHAR(DATE_PART('epoch_millisecond', b.ts)),
                       TO_VARCHAR(b.ts, 'YYYY-MM-DD"T"HH24:MI:SS')),
    -- About 3% of rows arrive with no customer id at all.
    'customer_id', IFF(MOD(ABS(HASH(b.n, 17)), 33) = 0,
                       NULL,
                       'C' || LPAD(MOD(ABS(HASH(b.n, 19)), 1500) + 1, 6, '0')),
    'currency',    DECODE(MOD(ABS(HASH(b.n, 23)), 8), 0,'EUR',1,'GBP',2,'JPY','USD'),
    'channel',     DECODE(MOD(ABS(HASH(b.n, 29)), 4), 0,'mobile',1,'partner','web'),
    'items',       ARRAY_CONSTRUCT(
                     OBJECT_CONSTRUCT(
                       'sku',       'SKU-' || LPAD(MOD(ABS(HASH(b.n, 31)), 300) + 1, 5, '0'),
                       'qty',       MOD(ABS(HASH(b.n, 37)), 4) + 1,
                       'unit_price', ROUND(5 + MOD(ABS(HASH(b.n, 41)), 200) + 0.5, 2)
                     ),
                     OBJECT_CONSTRUCT(
                       'sku',       'SKU-' || LPAD(MOD(ABS(HASH(b.n, 43)), 300) + 1, 5, '0'),
                       'qty',       MOD(ABS(HASH(b.n, 47)), 3) + 1,
                       'unit_price', ROUND(5 + MOD(ABS(HASH(b.n, 53)), 200) + 0.5, 2)
                     )
                   )
  )                                             AS PAYLOAD,
  'orders_' || TO_VARCHAR(b.ts, 'YYYYMMDD') || '.json' AS SOURCE_FILE,
  b.ts                                          AS INGESTED_AT
FROM base b;

-- The duplicate pass: re-deliver about 6% of events with a new RAW_ID
-- and a later INGESTED_AT, exactly as an at-least-once pipeline would.
INSERT INTO RAW_ORDER_EVENTS (RAW_ID, PAYLOAD, SOURCE_FILE, INGESTED_AT)
SELECT
  RAW_ID + 1000000,
  PAYLOAD,
  SOURCE_FILE,
  DATEADD('minute', 90, INGESTED_AT)
FROM RAW_ORDER_EVENTS
WHERE MOD(ABS(HASH(RAW_ID, 59)), 100) < 6;

-- ------------------------------------------------------------
-- Register this run for the Lab 62 cost capstone
-- ------------------------------------------------------------
INSERT INTO IDENTIFIER($RUN_LOG)
  (LAB_ID, LAB_NAME, EVENT_TYPE, EVENT_TS, USER_NAME, ROLE_NAME,
   WAREHOUSE_NAME, SESSION_ID, QUERY_TAG)
SELECT 'LAB22', 'Build a pipeline with dbt', 'SETUP', CURRENT_TIMESTAMP(),
       CURRENT_USER(), CURRENT_ROLE(), CURRENT_WAREHOUSE(),
       CURRENT_SESSION(), CURRENT_QUERY_TAG();

-- ------------------------------------------------------------
-- Confirm. Compare to the table in README.md.
--
-- Note the customer_id test. A missing key stored via
-- OBJECT_CONSTRUCT_KEEP_NULL becomes a JSON null, which is NOT the
-- same as a SQL NULL: `PAYLOAD:customer_id IS NULL` returns zero
-- rows here. You need IS_NULL_VALUE(), or a cast to a SQL type
-- first. dbt does not change this: a `not_null` test on a column
-- selected as PAYLOAD:customer_id passes for every row, because the
-- JSON null is a value. That is worth seeing for yourself.
-- ------------------------------------------------------------
SELECT
  COUNT(*)                                            AS TOTAL_RAW_ROWS,
  COUNT(DISTINCT PAYLOAD:event_id::STRING)            AS DISTINCT_EVENTS,
  COUNT(*) - COUNT(DISTINCT PAYLOAD:event_id::STRING) AS DUPLICATE_ROWS,
  COUNT_IF(IS_NULL_VALUE(PAYLOAD:customer_id))        AS NULL_CUSTOMER_ROWS,
  COUNT_IF(PAYLOAD:customer_id IS NULL)               AS NULL_CUSTOMER_WRONG_TEST
FROM RAW_ORDER_EVENTS;

-- ------------------------------------------------------------
-- Your object names, for pasting into CoCo and into the dbt profile
--
-- CoCo runs in its own session and cannot see the variables above,
-- so give it the real names. Copy the value, not the variable.
-- YOUR_DBT_TARGET_SCHEMA is the one to put in dbt_projects_profiles.yml.
-- ------------------------------------------------------------
SELECT $LAB_DB                 AS YOUR_LAB_DATABASE,
       $LAB_DB || '.LAB'       AS YOUR_LAB_SCHEMA,
       $LAB_DB || '.LAB_DBT'   AS YOUR_DBT_TARGET_SCHEMA,
       $WH                     AS YOUR_WAREHOUSE,
       $SHARED_DB              AS YOUR_SHARED_DATABASE;
